<script setup lang="ts">
import { computed, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Folder, FolderOpened, ArrowRight, ArrowUp, Search, Refresh, Download, VideoPlay, Document, Box, Picture, MoreFilled } from '@element-plus/icons-vue'
import type { Resource } from '../types'
const props = defineProps<{ api: (path: string) => Promise<any>; items: Resource[]; total: number; page: number; loading: boolean; parent: string; ancestors: { id: string; name: string }[]; search: string; type: string; recursive: boolean; theme: string; selected:Resource[] }>()
const emit = defineEmits<{ folder: [id: string]; search: [value: string]; type: [value: string]; recursive: [value: boolean]; page: [value: number]; open: [file: Resource]; download: [file: Resource]; preview: [file: Resource]; action: [action: string, file: Resource]; refresh: []; select:[files:Resource[]]; trash:[file:Resource] }>()
const treeVersion = ref(0), treeError = ref('')
const resourceTable = ref<{ clearSelection: () => void }>()
const isGallery = computed(() => props.theme === 'library')
const categories = [{ id: '', label: '全部' }, { id: 'resource', label: '文件' }, { id: 'video', label: '视频' }, { id: 'archive', label: '压缩包' }]
const currentName = computed(() => props.ancestors.at(-1)?.name || '公司资料')
function size(n: number) { if (!n) return '0 B'; const u = ['B','KB','MB','GB','TB'], i = Math.min(Math.floor(Math.log(n) / Math.log(1024)),4); return `${(n / 1024 ** i).toFixed(i > 1 ? 1 : 0)} ${u[i]}` }
function kind(f: Resource) { return f.kind === 'folder' ? 'folder' : f.mime.startsWith('video/') ? 'video' : /\.(zip|rar|7z|tar|gz|tgz|bz2|xz)$/i.test(f.name) ? 'archive' : f.mime.startsWith('image/') ? 'image' : 'file' }
function fileIcon(f: Resource) { return ({ folder: Folder, video: VideoPlay, archive: Box, image: Picture, file: Document })[kind(f)] }
function ready(f: Resource) { return f.can_download }
function imagePreviewable(f: Resource) { return ['image/jpeg','image/png','image/gif','image/webp','image/avif','image/bmp'].includes(f.mime) }
function playable(f: Resource) { return ['video/mp4','video/webm'].includes(f.mime) }
function state(f: Resource) { if(f.kind==='folder')return '';if(f.source_missing)return '源文件缺失';return [f.publication==='pending'?'待发布审核':f.publication==='rejected'?'审核未通过':'',f.scan_warning?'未执行病毒检查':f.scan_status==='clean'?'':({pending:'待安全检查',scanning:'安全检查中',failed:'检查失败',infected:'已阻止访问'}[f.scan_status]||f.scan_status)].filter(Boolean).join(' · ') }
async function loadTree(node: any, resolve: (items: any[]) => void, reject?: () => void) { if (node.level === 0) { resolve([{ id: '', name: '公司资料' }]); return }; try { treeError.value = ''; resolve(await props.api(`/company/folders?parent=${encodeURIComponent(node.data.id)}`)) } catch (e: any) { treeError.value = e.message; ElMessage.error(e.message); if (reject) reject(); else resolve([]) } }
function toggleSelected(f:Resource,value:boolean) {emit('select',value ? [...props.selected.filter(item => item.id !== f.id),f] : props.selected.filter(item => item.id !== f.id))}
function refreshTree() { treeVersion.value++; treeError.value = '' }
defineExpose({ refreshTree, clearSelection: () => resourceTable.value?.clearSelection() })
</script>
<template>
  <section :class="['company-browser', { 'gallery-browser': isGallery }]"><aside class="directory-panel"><div class="directory-title"><span>公司目录</span><el-button :icon="Refresh" text circle aria-label="刷新目录树" @click="refreshTree"/></div><el-tree :key="treeVersion" node-key="id" :props="{ label:'name' }" lazy :load="loadTree" highlight-current :current-node-key="parent" :default-expanded-keys="['']" :expand-on-click-node="false" @node-click="(node: any) => emit('folder',node.id)"><template #default="{ data }"><span class="directory-node"><el-icon><Folder/></el-icon><span :title="data.name">{{ data.name }}</span></span></template></el-tree><p v-if="treeError" class="error-text">目录加载失败，可点击刷新重试。</p><div class="directory-help">按电脑文件夹层级浏览<br>公司资料全员可见</div></aside>
    <div class="company-files files-panel"><div class="company-address"><el-button :icon="ArrowUp" text :disabled="!parent" aria-label="返回上一级" @click="emit('folder',ancestors.at(-2)?.id || '')"/><nav aria-label="当前位置"><button @click="emit('folder','')"><el-icon><FolderOpened/></el-icon>公司资料</button><template v-for="a in ancestors" :key="a.id"><el-icon><ArrowRight/></el-icon><button @click="emit('folder',a.id)">{{ a.name }}</button></template></nav><el-button :icon="Refresh" text aria-label="刷新公司资料" @click="emit('refresh'); refreshTree()"/></div>
    <div class="company-tools"><div class="company-categories" aria-label="资源分类"><button v-for="c in categories" :key="c.id" :aria-pressed="type === c.id" :class="{ active:type === c.id }" @click="emit('type',c.id)">{{ c.label }}</button></div><el-input :model-value="search" :prefix-icon="Search" clearable aria-label="搜索公司文件名或备注" placeholder="搜索文件名或备注" @update:model-value="emit('search',String($event))"/></div><div class="company-range"><span>{{ currentName }} · {{ total }} 个项目</span><el-checkbox :model-value="recursive" @update:model-value="emit('recursive',Boolean($event))">包含子目录</el-checkbox></div>
    <el-table ref="resourceTable" v-if="!isGallery" v-loading="loading" :data="items" class="file-table company-table" empty-text="当前范围没有匹配的资料，可切换分类或包含子目录" row-key="id" @selection-change="emit('select',$event)" @row-dblclick="emit('open',$event)"><el-table-column type="selection" width="44"/><el-table-column label="名称 / 备注" min-width="220"><template #default="{ row }"><button class="file-name-cell" @click="emit('open',row)"><span :class="['file-icon',kind(row)]"><el-icon><component :is="fileIcon(row)"/></el-icon></span><span class="file-name-text"><strong>{{ row.name }}</strong><small :title="row.remark">{{ row.remark || (row.kind === 'folder' ? '文件夹' : '暂无备注') }}</small></span></button></template></el-table-column><el-table-column label="大小" width="90"><template #default="{ row }">{{ row.kind === 'folder' ? '—' : size(row.size) }}</template></el-table-column><el-table-column label="操作" width="310" align="right"><template #default="{ row }"><template v-if="row.kind === 'folder'"><el-button link type="primary" @click="emit('open',row)">打开</el-button><el-button link type="primary" @click="emit('download',row)">下载目录</el-button></template><template v-else><el-button v-if="ready(row) && imagePreviewable(row)" link type="primary" @click="emit('preview',row)">预览</el-button><el-button v-if="ready(row) && playable(row)" link type="primary" @click="emit('preview',row)">播放</el-button><el-button v-if="ready(row)" link type="primary" @click="emit('download',row)">下载</el-button><span v-if="state(row)" class="company-file-status">{{ state(row) }}</span></template><el-button v-if="row.can_manage" link type="danger" @click="emit('trash',row)">移入回收站</el-button><el-dropdown trigger="click" @command="(action: string) => emit('action',action,row)"><el-button text circle :icon="MoreFilled" :aria-label="'操作 '+row.name"/><template #dropdown><el-dropdown-menu><el-dropdown-item command="details">查看详情</el-dropdown-item><el-dropdown-item v-if="row.kind === 'folder'" command="download">下载目录 ZIP</el-dropdown-item><el-dropdown-item v-if="ready(row) && imagePreviewable(row)" command="preview">图片预览</el-dropdown-item><el-dropdown-item command="link">复制内部链接</el-dropdown-item><el-dropdown-item v-if="row.can_manage" command="edit">编辑名称和备注</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table>
    <div v-else v-loading="loading" class="company-gallery"><article v-for="f in items" :key="f.id" :class="['company-resource-card',kind(f)]"><el-checkbox :model-value="selected.some(item => item.id === f.id)" :aria-label="'选择 ' + f.name" @update:model-value="toggleSelected(f,Boolean($event))"/><button :aria-label="(f.kind === 'folder' ? '打开文件夹 ' : '查看 ') + f.name" class="company-cover" @click="f.kind === 'folder' ? emit('open',f) : (playable(f) || imagePreviewable(f)) && ready(f) ? emit('preview',f) : emit('open',f)"><span>{{ kind(f) === 'video' ? 'GMPAN / VIDEO' : f.kind === 'folder' ? 'DIRECTORY' : 'DOCUMENT' }}</span><el-icon><component :is="fileIcon(f)"/></el-icon><strong>{{ f.name }}</strong></button><div class="company-card-info"><button class="company-card-name" @click="emit('open',f)">{{ f.name }}</button><p :title="f.remark">{{ f.remark || (f.kind === 'folder' ? '打开文件夹浏览资料' : '暂无备注') }}</p><div><span>{{ f.kind === 'folder' ? '文件夹' : size(f.size) }}</span><span v-if="state(f)" class="company-file-status">{{ state(f) }}</span><el-button v-if="ready(f) && imagePreviewable(f)" link type="primary" @click="emit('preview',f)">预览</el-button><el-button v-if="ready(f) || f.kind === 'folder'" link type="primary" :icon="Download" @click="emit('download',f)">{{ f.kind === 'folder' ? '下载目录' : '下载' }}</el-button><el-button v-if="f.can_manage" link type="danger" @click="emit('trash',f)">移入回收站</el-button></div></div></article><el-empty v-if="!items.length" description="当前范围没有匹配的资料"/></div>
    <div class="company-browser-footer"><span>{{ recursive ? '当前目录及子目录' : '当前目录' }} · 名称或备注匹配</span><el-pagination :current-page="page" :page-size="50" :total="total" layout="prev, pager, next" hide-on-single-page @current-change="emit('page',$event)"/></div></div>
  </section>
</template>
